steps.script:
function transform(ctx) {
  var mac = (ctx.local_mac || "").toLowerCase();
  var ip = ctx.local_ip || "";
  var payload = {
    deviceType: "Android",
    webAuthUser: ctx.username || "",
    webAuthPassword: ctx.password || "",
    redirectUrl: "http://10.16.0.12:8081/?usermac=" + mac + "&userip=" + ip + "&origurl=http://edge.microsoft.com/captiveportal/generate_204&nasip=10.100.0.1",
    type: "login"
  };
  return { body_json: JSON.stringify(payload) };
}
